INSERT INTO `products` (`id`, `category_id`, `sub_category_id`, `sub_sub_category_id`, `sku`, `name`, `price`, `price_old`, `description`, `advantages`, `usage_guide`, `image`, `material`, `style`, `color`, `warranty`, `width`, `depth`, `height`, `created_at`, `updated_at`) VALUES
('3', '55', '2', NULL, 'BGĐ16', 'Bàn Giám Đốc Góc L Yếm Lửng - vân gỗ', '8500000', NULL, 'Bàn Giám Đốc Góc L Yếm Lửng – BGĐ16 được thiết kế mặt bàn chính uốn cong công phu nối liền tạo thành phần chân vững chắc mang tăng tính thẩm mỹ cao. Mặt bàn làm bằng chất liệu nhập khẩu nhẵn bóng dễ dàng lau chùi bằng khăn giấy hoặc khăn mềm. Tủ phụ được đặt vuông góc với mặt chính thành hình chữ L theo phong thủy thì bàn sẽ giúp người sở hữu thu hút được tài lộc nên thường được các lãnh đạo ưa chuộng. Phần yếm bàn dạng lửng tạo sự thông thoáng cho người sử dụng. Màu bàn trẻ trung được phối xe kẻ vô cùng bắt mắt.', '+ Kiểu dáng bàn đẹp thẩm mỹ cao \r\n\r\n+ Bên trong tủ phụ hồ sơ nhiều tính năng và công năng lưu trữ tài liệu an toàn và bảo mật\r\n+ Trên mặt bàn có lỗ luồn dây điện giúp gọn gàng và an toàn khi sử dụng\r\n+ Màu sắc được lựa chọn màu bàn yêu thích \r\n+ Mặt bàn nhẵn bóng dễ dàng lau chùi vệ sinh', 'Không để tủ gỗ dính nước quá lâu mặc dù đã qua công nghệ xử lý có thể chống thấm, , ít bị ảnh hưởng nước. Nhưng để bảo quản các mẫu bàn đúng cách thì nên hạn chế cho bàn tiếp xúc với nước.\r\n+ Tránh va đập mạnh vào tủ gỗ quá mạnh\r\n+ Vệ sinh đúng cách bàn làm việc văn phòng gỗ công nghiệp', 'products/xOorEkFd4NrNxa0TmII0dWqrTYqaMDQKDPw1cmgc.jpg', 'Mặt bàn và tủ MDF phủ Melamine, Chân khung bàn bằn thép tấm tạo hình sơn màu tùy chọn', 'Chuyên nghiêp, lịch sự', NULL, NULL, NULL, NULL, NULL, '2026-08-19 09:18:26', '2026-08-24 08:16:24'),
('5', '55', '3', NULL, 'BLV135', 'Bàn Làm Việc Chân Sắt Chữ L Yếm Lửng Chắc Chắn - BLV 135', '4000000', NULL, 'Bàn Làm Việc Chân Sắt Chữ L Yếm Lửng Chắc Chắn là giải pháp lý tưởng cho văn phòng hiện đại cần tối ưu không gian. Thiết kế chữ L mở rộng mặt bàn, dễ dàng bố trí máy tính, tài liệu và thiết bị cá nhân. Phần yếm lửng vừa tạo sự riêng tư nhẹ nhàng, vừa đảm bảo sự thông thoáng cho không gian làm việc. Khung chân sắt sơn tĩnh điện chịu lực tốt, giúp bàn luôn chắc chắn trong suốt quá trình sử dụng. Mặt bàn làm từ gỗ công nghiệp phủ Melamine chống trầy xước, chống ẩm, dễ lau chùi. Với kiểu dáng tối giản, hiện đại, bàn làm việc chân sắt chữ L yếm lửng phù hợp nhiều phong cách nội thất và dễ phối hợp với ghế xoay, tủ phụ, kệ sách trong văn phòng.', 'Thiết kế chữ L tối ưu không gian: Giúp mở rộng tối đa diện tích mặt bàn, linh hoạt bố trí máy tính, tài liệu và thiết bị cá nhân gọn gàng.\r\nYếm lửng thông thoáng & riêng tư: Tạo độ kín đáo nhẹ nhàng cho người ngồi nhưng vẫn giữ sự thông thoáng, thoải mái cho không gian làm việc.\r\nKhung chân chắc chắn, bền bỉ: Chất liệu thép sơn tĩnh điện chống gỉ sét, kết cấu chịu lực tốt, giảm thiểu rung lắc trong suốt quá trình sử dụng.\r\nMặt gỗ Melamine cao cấp: Bề mặt mịn, chống xước, chống ẩm mốc tốt, phù hợp với điều kiện khí hậu Việt Nam.\r\nKiểu dáng hiện đại, dễ phối đồ: Kiểu dáng tối giản phù hợp với nhiều phong cách nội thất văn phòng, dễ kết hợp cùng ghế xoay, tủ phụ hay kệ sách.', 'Vệ sinh: Lau chùi mặt bàn bằng khăn mềm ẩm; không dùng chất tẩy rửa hóa học mạnh để bảo vệ lớp phủ Melamine.\r\nVị trí đặt bàn: Đặt bàn trên bề mặt bằng phẳng, tránh nơi ẩm thấp hoặc có ánh nắng mặt trời chiếu trực tiếp thời gian dài.\r\nBảo dưỡng: Định kỳ kiểm tra và siết lại các điểm nối, ốc vít sau một thời gian sử dụng.\r\nTải trọng: Bố trí vật dụng hợp lý, tránh đặt đồ vật quá nặng vượt quá tải trọng cho phép.', 'products/23B1pE2EwMOrqPjFhfBJ0hHCDNcP0KvDUPIggMVT.png', 'Mặt Bàn MDF, Phủ Melamine, Thép ống tam giác sơn tĩnh điện trắng/đen', 'Hiện đại', NULL, '12 Tháng ( Bảo Hành Mối Mọt)', NULL, NULL, NULL, '2026-09-07 07:45:59', '2026-09-07 07:45:59'),
('6', '55', '4', '4', 'BC115', 'Cụm Bàn Làm Việc 4 Người Có Vách Ngăn Kệ Sách - BC115', '10000000', '11200000', 'Cụm bàn 4 người tích hợp vách ngăn và kệ sách trung tâm, tăng riêng tư và không gian lưu trữ. Phù hợp văn phòng open-space.', 'Vách ngăn giảm tiếng ồn\r\nKệ sách trung tâm tiện dụng\r\nChân sắt chắc chắn\r\nMặt bàn Melamine chống xước', 'Lắp đặt theo hướng dẫn. Không kê sát tường kín gió. Lau bề mặt bằng khăn mềm.', 'products/52ZF6JsxfwkiLG24IIqACcxH9HXcE0lFkrRbZddX.png', 'Gỗ công nghiệp Melamine + chân sắt sơn tĩnh điện', 'Hiện đại, có vách ngăn & kệ sách', NULL, '12 tháng', NULL, NULL, NULL, '2026-09-07 07:52:13', '2026-09-14 06:10:23'),
('7', '55', '4', '4', 'BC114', 'Cụm Bàn Làm Việc 4 Người Khung Sắt Lưới Mới Lạ - BC114', '8000000', '8800000', 'Thiết kế khung sắt lưới tạo điểm nhấn hiện đại, thoáng khí. Module 4 chỗ ngồi đối xứng.', 'Khung sắt lưới bền đẹp\r\nDễ tháo lắp module\r\nPhù hợp không gian trẻ trung\r\nGiá hợp lý', 'Kiểm tra ốc vít định kỳ 3–6 tháng. Tránh đặt vật nặng lệch một góc bàn.', 'products/bgaSqcbNhHA8HQSf7yMAENhllV6Kqt3COluRL2Vz.png', 'Mặt gỗ công nghiệp + khung sắt lưới', 'Công nghiệp, khung lưới độc đáo', NULL, '12 tháng', NULL, NULL, NULL, '2026-09-07 07:52:13', '2026-09-14 06:10:36'),
('8', '55', '4', '4', 'BC113', 'Cụm Bàn Làm Việc 4 Người Khung Sắt Chữ K Hiện Đại - BC113', '4950000', '5200000', 'Chân sắt chữ K chắc chắn, thiết kế tối giản. Phù hợp startup và văn phòng nhỏ.', 'Chân chữ K vững chắc\r\nGiá cạnh tranh\r\nLắp đặt nhanh\r\nNhiều màu mặt bàn', 'Đặt trên nền phẳng. Không đứng lên mặt bàn.', 'products/WUlNnxHVkxDKeKbksIAc4hGCpP9RJaDrqQyF8Y35.png', 'Gỗ công nghiệp + chân sắt chữ K sơn tĩnh điện', 'Tối giản, chân chữ K', NULL, '12 tháng', NULL, NULL, NULL, '2026-09-07 07:52:13', '2026-09-14 06:10:45'),
('9', '55', '4', '4', 'BC111', 'Cụm Bàn Làm Việc 4 Người Chữ Thập Độc Đáo - BC111', '7900000', '9950000', 'Bố cục chữ thập tạo không gian giao tiếp nhóm tốt, mỗi người có góc làm việc riêng.', 'Bố cục chữ thập sáng tạo\r\nTăng tương tác nhóm\r\nMặt bàn chống ẩm\r\nBảo hành 18 tháng', 'Cần diện tích sàn tối thiểu khoảng 3m x 3m. Lau bằng khăn ẩm, không dùng hóa chất mạnh.', 'products/iOr4x9PCZVHVQ0145tQBk154X0CetySpt0O1v8AL.png', 'Melamine cao cấp + khung sắt chữ thập', 'Độc đáo, bố cục chữ thập', NULL, '18 tháng', NULL, NULL, NULL, '2026-09-07 07:52:13', '2026-09-14 06:10:54'),
('10', '57', '8', NULL, 'BT26', 'Bàn Trà Sofa Mặt Vân Đá 2 Hộc Tủ Hiện Đại', '2100000', NULL, 'Bàn trà sofa là một món đồ nội thất hiện đại và sang trọng. Mặt vân đá tự nhiên tạo nên vẻ đẹp độc đáo, trong khi 2 hộc lưu trữ giúp giữ không gian sạch sẽ. Thiết kế tinh tế và tủ hiện đại đi kèm tạo nên một không gian phòng khách hoàn chỉnh và tiện nghi.', 'Ưu Điểm :\r\nThiết kế hiện đại và sang trọng\r\n  +Thiết kế tinh tế và hiện đại phù hợp với phong cách của các gia đình trẻ và hiện đại\r\nTiện lợi và thông minh\r\n  +2 hộc lưu trữ thông minh giúp giữ không gian luôn ngăn nắp và sạch sẽ\r\n  +Tủ hiện đại đi kèm tạo nên một không gian lưu trữ rộng rãi và tiện lợi\r\nChất lượng cao cấp\r\n  +Mặt bàn làm từ vân đá tự nhiên cao cấp đảm bảo độ bền và ổn định\r\nPhù hợp với nhiều không gian\r\n  +Kích thước bàn và tủ phù hợp với nhiều không gian phòng khách khác nhau\r\n  +Màu sắc đen và trắng sang trọng và tinh tế phù hợp với nhiều phong cách thiết kế nội thất', 'Lưu Ý :\r\n- Đối với các mẫu có sẵn như thời gian giao hàng sẽ từ 1-2 ngày.\r\n- Đối với các sản phẩm do khách hàng đặt hàng, thời gian giao hàng sẽ từ 3-7 ngày kể từ khi đặt hàng.\r\n- Chính sách bảo hành minh bạch 12 tháng tiêu chuẩn nhà máy.\r\n- Điều kiện bảo hành: Sản phẩm còn thời hạn bảo hành, còn phiếu bảo hành hoặc hóa đơn mua hàng. Các sản phẩm hư hỏng được xác định do lỗi sản xuất hoặc lắp đặt gây ra', 'products/AGPuAorvrShhTJRpy0t9tsi3hfgal2Vnv8tlMNTu.png', 'Mặt Bàn Kính Cường Lực Khung Gỗ MDF Sơn Chống Thấm Công Nghệ', 'Hiện đại và sang trọng', 'Đá kim sa, Đá nung kết, Đá Vicostone', '12 Tháng', NULL, NULL, NULL, '2026-09-14 07:11:46', '2026-09-14 07:42:10');
